import { UseSortByColumnProps } from 'react-table';
import { css, FlattenSimpleInterpolation } from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Typography from '@dynatrace/strato-design-tokens/typography';

/** Applies cell sorted styles for header cells. */
export function sortedHeaderCellCss(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  canSort?: UseSortByColumnProps<any>['canSort'],
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  isSorted?: UseSortByColumnProps<any>['isSorted'],
): FlattenSimpleInterpolation {
  if (canSort) {
    return css`
      transition-duration: ${Animations.Hover.Duration.Base};
      transition-timing-function: ${Animations.Hover.Easing};

      color: ${isSorted
        ? Colors.Text.Primary.Default
        : Colors.Text.Neutral.Default};

      .strato-table-sort-icon {
        color: ${isSorted
          ? Colors.Icon.Primary.Default
          : Colors.Icon.Neutral.Default};
      }

      :hover {
        background: ${isSorted
          ? Colors.Background.Field.Primary.DefaultHover
          : Colors.Background.Field.Neutral.DefaultHover};

        .strato-table-sort-icon {
          color: ${isSorted
            ? Colors.Icon.Primary.Default
            : Colors.Icon.Neutral.Default};
        }
      }
    `;
  }
  return css``;
}

/** Applies cell sorted styles for body cells. */
export function sortedBodyCellCss({
  isSorted,
}: // eslint-disable-next-line @typescript-eslint/no-explicit-any
Partial<UseSortByColumnProps<any>>): FlattenSimpleInterpolation {
  if (isSorted) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return css({ fontWeight: Typography.Text.Base.Emphasized.Weight as any });
  }
  return css({});
}
